   295	ReadCompressedCharData(mat_t *mat,z_streamp z,char *data,
   296	    enum matio_types data_type,int len)
   297	{
   298	    int nBytes = 0;
   299	    unsigned int data_size;
   300	
   301	    if ( mat == NULL || data == NULL || mat->fp == NULL )
   302	        return 0;
   303	
   304	    data_size = (unsigned int)Mat_SizeOf(data_type);
   305	
   306	    switch ( data_type ) {
   307	        case MAT_T_UINT8:
   308	        case MAT_T_UTF8:
   309	            InflateData(mat,z,data,len*data_size);
   310	            break;
   311	        case MAT_T_UINT16:
   312	        case MAT_T_UTF16:
   313	            InflateData(mat,z,data,len*data_size);
   314	            if ( mat->byteswap ) {
   315	                int i;
   316	                for ( i = 0; i < len; i++ ) {
   317	                    Mat_uint16Swap((mat_uint16_t*)&data[2*i]);
   318	                }
   319	            }
   320	            break;
   321	        default:
   322	            Mat_Warning("ReadCompressedCharData: %d is not a supported data "
   323	                "type for character data", data_type);
   324	            break;
   325	    }
   326	    nBytes = len*data_size;
